CREATE USER StudyReader WITHOUT LOGIN;
GRANT SELECT ON OBJECT::dbo.StudyOrders TO StudyReader;
-- Authorized lab operator: EXECUTE AS USER = 'StudyReader';
-- Compare SELECT with UPDATE; REVERT before cleanup.

-- SQL over already prepared fixture
SELECT Region, SUM(Quantity * UnitPrice) AS Revenue
FROM dbo.StudySales WHERE Status = 'Posted' GROUP BY Region;

// KQL over typed fixture
StudySales | where Status == "Posted" | extend Revenue = Quantity * UnitPrice | summarize Total = sum(Revenue) by Region

// DAX measure; Region in visual grouping
Posted Revenue = CALCULATE(SUMX(StudySales, StudySales[Quantity] * StudySales[UnitPrice]), StudySales[Status] = "Posted")
